 add('D20','Known-dependent provider cannot qualify name route','CCO',['CCO'],'UNIQUE_CANONICAL_MATCH',category_override='QUALIFIED_NAME',source_name='ethanol',external_fixture='KNOWN_DEPENDENT',expected_ids=['FIX_1'],expected_admission='UNRESOLVED')
 add('D21','Unknown dependence is existing policy behavior, not audited independence','CCO',['CCO'],'UNIQUE_CANONICAL_MATCH',category_override='QUALIFIED_NAME',source_name='ethanol',external_fixture='UNKNOWN_DEPENDENCE',expected_ids=['FIX_1'],expected_admission='AUTO_ACCEPT')
