 write(H/'controls/benchmark_freeze.json',dict(files={f'{k}_controls.json':hashlib.sha256((H/f'controls/{k}_controls.json').read_bytes()).hexdigest() for k in ('development','heldout')},expectations_generated_by_resolver=False))
